+struct OpenCalls<'a> {
+    /// `(call_id, name)` in open order.
+    open: Vec<(&'a str, &'a str)>,
+    /// Ids opened so far.
+    seen: HashSet<&'a str>,
+    /// Ids of every call in the conversation (error-message choice only).
+    all: HashSet<&'a str>,
+}
+
+impl<'a> OpenCalls<'a> {
+    fn new(items: &'a [Item]) -> Self {
+        let mut all = HashSet::new();
+        for it in items {
